function esc(v){return String(v??"").replace(/[&<>"']/g,function(c){return({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c])})}
function clone(v){return JSON.parse(JSON.stringify(v))}

/* ===== v13.9 Shared Flashcards Engine (content banks intentionally empty) ===== */
let flashcardDeckId=null;

function flashcardSubjectId(){
  return activeSubject==="tu101"?"tu101":"ec214";
}
function flashcardStorageKey(subjectId){
  return activeUser?"d-study-flashcards::"+subjectId+"::"+activeUser.id:"";
}
function freshFlashcardStore(subjectId){
  return{version:1,subjectId:subjectId,decks:{}};
}
function flashcardBank(subjectId){
  const external=window.D_STUDY_FLASHCARD_BANKS&&window.D_STUDY_FLASHCARD_BANKS[subjectId];
  if(external&&typeof external==="object")return external;
  return{title:(subjectId==="tu101"?"TU101":"EC214")+" Flashcards",parts:[]};
}
function normalizedFlashcardDecks(subjectId){
  const bank=flashcardBank(subjectId),parts=(Array.isArray(bank.parts)?bank.parts:[]).map(function(part,pi){
    const pid=String(part.id||("part-"+(pi+1)));
    const cards=(Array.isArray(part.cards)?part.cards:[]).map(function(card,ci){
      return{id:pid+"::"+String(card.id||("card-"+(ci+1))),front:String(card.front||""),back:String(card.back||""),partId:pid};
    }).filter(function(card){return card.front&&card.back});
    return{id:pid,label:String(part.label||("Part "+(pi+1))),description:String(part.description||""),cards:cards,cumulative:false};
  });
  const all=[];
  parts.forEach(function(part){part.cards.forEach(function(card){all.push(Object.assign({},card))})});
  if(all.length)parts.push({id:"cumulative",label:"Cumulative",description:"All flashcards from every part in this subject.",cards:all,cumulative:true});
  return parts;
}
function quarantineFlashcardRaw(subjectId,raw){
  if(!activeUser||!raw)return;
  try{localStorage.setItem("d-study-flashcards-quarantine::"+activeUser.id+"::"+Date.now(),raw)}catch(_){}
}
function loadFlashcardStore(subjectId){
  const key=flashcardStorageKey(subjectId);if(!key)return freshFlashcardStore(subjectId);
  const raw=localStorage.getItem(key);if(!raw)return freshFlashcardStore(subjectId);
  try{
    const x=JSON.parse(raw);
    if(!x||typeof x!=="object"||x.subjectId!==subjectId){quarantineFlashcardRaw(subjectId,raw);return freshFlashcardStore(subjectId)}
    x.version=1;x.decks=x.decks&&typeof x.decks==="object"?x.decks:{};
    return x;
  }catch(_){quarantineFlashcardRaw(subjectId,raw);return freshFlashcardStore(subjectId)}
}
function saveFlashcardStore(subjectId,store){
  if(!activeUser||!store)return false;
  if(store.subjectId!==subjectId){quarantineFlashcardRaw(subjectId,JSON.stringify(store));return false}
  localStorage.setItem(flashcardStorageKey(subjectId),JSON.stringify(store));return true;
}
function fcShuffle(items){
  const a=items.slice();
  for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=a[i];a[i]=a[j];a[j]=t}
  return a;
}
function flashcardDeck(subjectId,deckId){
  return normalizedFlashcardDecks(subjectId).find(function(d){return d.id===deckId})||null;
}
function ensureFlashcardDeckProgress(store,deckId){
  if(!store.decks[deckId]||typeof store.decks[deckId]!=="object"){
    store.decks[deckId]={completionCount:0,totalRatings:0,lastCompletedAt:null,session:null};
  }
  const p=store.decks[deckId];
  p.completionCount=Number(p.completionCount)||0;p.totalRatings=Number(p.totalRatings)||0;
  return p;
}
function startFlashcardCycle(deckId,shuffleFirst){
  const subjectId=flashcardSubjectId(),deck=flashcardDeck(subjectId,deckId);if(!deck||!deck.cards.length)return;
  const store=loadFlashcardStore(subjectId),dp=ensureFlashcardDeckProgress(store,deckId);
  const ids=deck.cards.map(function(c){return c.id});
  dp.session={phase:"first",queue:shuffleFirst?fcShuffle(ids):ids.slice(),index:0,missed:[],revealed:false,retryRound:0,startedAt:new Date().toISOString()};
  saveFlashcardStore(subjectId,store);flashcardDeckId=deckId;renderFlashcards();
}
function flashcardCompleteCycle(subjectId,store,dp){
  dp.completionCount=(Number(dp.completionCount)||0)+1;dp.lastCompletedAt=new Date().toISOString();
  dp.session={phase:"complete",queue:[],index:0,missed:[],revealed:false,retryRound:0,completedAt:dp.lastCompletedAt};
  saveFlashcardStore(subjectId,store);
}
function rateFlashcard(remembered){
  const subjectId=flashcardSubjectId(),deck=flashcardDeck(subjectId,flashcardDeckId);if(!deck)return;
  const store=loadFlashcardStore(subjectId),dp=ensureFlashcardDeckProgress(store,deck.id),session=dp.session;
  if(!session||!["first","retry"].includes(session.phase)||!session.revealed)return;
  const id=session.queue[session.index];if(!id)return;
  dp.totalRatings=(Number(dp.totalRatings)||0)+1;
  if(remembered)session.missed=session.missed.filter(function(x){return x!==id});
  else if(!session.missed.includes(id))session.missed.push(id);
  session.index++;session.revealed=false;
  if(session.index>=session.queue.length){
    if(session.missed.length===0){flashcardCompleteCycle(subjectId,store,dp);renderFlashcards();return}
    session.phase="retry";session.retryRound=(Number(session.retryRound)||0)+1;session.queue=fcShuffle(session.missed);session.index=0;
  }
  saveFlashcardStore(subjectId,store);renderFlashcards();
}
function toggleFlashcardAnswer(){
  const subjectId=flashcardSubjectId(),store=loadFlashcardStore(subjectId),dp=ensureFlashcardDeckProgress(store,flashcardDeckId),session=dp.session;
  if(!session||!["first","retry"].includes(session.phase))return;
  session.revealed=!session.revealed;saveFlashcardStore(subjectId,store);renderFlashcards();
}
function shuffleFlashcardRemaining(){
  const subjectId=flashcardSubjectId(),store=loadFlashcardStore(subjectId),dp=ensureFlashcardDeckProgress(store,flashcardDeckId),session=dp.session;
  if(!session||!["first","retry"].includes(session.phase))return;
  const before=session.queue.slice(0,session.index+1),after=fcShuffle(session.queue.slice(session.index+1));
  session.queue=before.concat(after);saveFlashcardStore(subjectId,store);renderFlashcards();
}
function resetFlashcardDeck(deckId){
  const subjectId=flashcardSubjectId(),deck=flashcardDeck(subjectId,deckId);if(!deck)return;
  if(!confirm("Reset all flashcard progress for "+deck.label+"? This resets its 100% completion count too."))return;
  const store=loadFlashcardStore(subjectId);delete store.decks[deckId];saveFlashcardStore(subjectId,store);renderFlashcards();
}
function resetAllFlashcards(){
  const subjectId=flashcardSubjectId(),name=subjectId==="tu101"?"TU101":"EC214";
  if(!confirm("Reset ALL "+name+" flashcard progress? Quiz/progress/notes are not affected."))return;
  saveFlashcardStore(subjectId,freshFlashcardStore(subjectId));flashcardDeckId=null;renderFlashcards();
}
function flashcardDeckStatus(deck,dp){
  if(!dp)return"Not started";
  if(dp.session&&dp.session.phase==="complete")return"100% complete";
  if(dp.session&&dp.session.phase==="first")return"First pass "+Math.min(dp.session.index+1,deck.cards.length)+"/"+deck.cards.length;
  if(dp.session&&dp.session.phase==="retry")return(dp.session.missed||[]).length+" still learning";
  return(Number(dp.completionCount)||0)>0?"Ready for another round":"Not started";
}
function flashcardProgressBadge(dp){
  return"100% × "+String(dp&&Number(dp.completionCount)||0);
}
function flashcardEmptyMarkup(subjectId){
  const name=subjectId==="tu101"?"TU101":"EC214";
  return '<div class="flashcard-empty-grid">'+
    '<article class="card flashcard-empty-card"><div class="eyebrow">Parts</div><h3>Part decks are ready</h3><p>No '+name+' flashcards have been added yet. When cards are created, they will be separated into focused parts here.</p></article>'+
    '<article class="card flashcard-empty-card"><div class="eyebrow">Cumulative</div><h3>Cumulative deck is ready</h3><p>Once part cards exist, Cumulative automatically combines all part cards while keeping its own saved review progress.</p></article>'+
    '</div><div class="card flashcard-behavior-card"><div class="lecture-title">How the flashcard cycle will work</div><div class="flashcard-feature-list"><span>Press card / Show answer</span><span>Shuffle remaining cards</span><span>Remembered</span><span>Haven’t remembered</span><span>Missed cards repeat randomly</span><span>100% completion counter</span><span>Autosave while playing</span><span>Reset deck progress</span></div><p class="small">No study cards were generated in this release, as requested.</p></div>';
}
function renderFlashcardLibrary(subjectId,decks,store){
  const partDecks=decks.filter(function(d){return!d.cumulative}),cumulative=decks.find(function(d){return d.cumulative});
  if(!decks.length)return flashcardEmptyMarkup(subjectId);
  function tile(deck){
    const dp=store.decks[deck.id],resume=dp&&dp.session&&["first","retry"].includes(dp.session.phase);
    return '<article class="card flashcard-deck-tile '+(deck.cumulative?'cumulative':'')+'"><div class="flashcard-deck-top"><div><div class="eyebrow">'+(deck.cumulative?'Cumulative':'Part')+'</div><h3>'+esc(deck.label)+'</h3><p class="small">'+esc(deck.description||"Focused flashcard review deck.")+'</p></div><span class="flashcard-100-badge">'+flashcardProgressBadge(dp)+'</span></div><div class="flashcard-deck-meta"><span>'+deck.cards.length+' cards</span><span>'+esc(flashcardDeckStatus(deck,dp))+'</span></div><div class="flashcard-deck-actions"><button type="button" data-fc-open="'+esc(deck.id)+'">'+(resume?'Resume':'Open deck')+'</button><button type="button" class="secondary" data-fc-reset="'+esc(deck.id)+'">Reset progress</button></div></article>';
  }
  return '<div class="flashcard-library-section"><div class="lecture-title">Parts</div><div class="small">Each part saves independently.</div><div class="flashcard-deck-grid">'+partDecks.map(tile).join("")+'</div></div>'+
    (cumulative?'<div class="flashcard-library-section"><div class="lecture-title">Cumulative</div><div class="small">All part cards together, with separate cumulative progress.</div><div class="flashcard-deck-grid">'+tile(cumulative)+'</div></div>':'');
}
function renderFlashcardSession(subjectId,deck,store){
  const dp=ensureFlashcardDeckProgress(store,deck.id),session=dp.session;
  if(!session){
    return '<div class="flashcard-session-head"><button type="button" class="secondary" data-fc-back>← All decks</button><span class="flashcard-100-badge">'+flashcardProgressBadge(dp)+'</span></div><div class="card flashcard-start-card"><div class="eyebrow">'+(deck.cumulative?'Cumulative':'Part')+'</div><h2>'+esc(deck.label)+'</h2><p>'+deck.cards.length+' cards. Your first pass goes through every card once. After that, only cards marked <b>Haven’t remembered</b> repeat in random order until none remain.</p><div class="flashcard-start-actions"><button type="button" data-fc-start>Start</button><button type="button" class="secondary" data-fc-start-shuffled>Start shuffled</button><button type="button" class="secondary" data-fc-reset="'+esc(deck.id)+'">Reset progress</button></div></div>';
  }
  if(session.phase==="complete"){
    return '<div class="flashcard-session-head"><button type="button" class="secondary" data-fc-back>← All decks</button><span class="flashcard-100-badge">'+flashcardProgressBadge(dp)+'</span></div><div class="card flashcard-complete-card"><div class="flashcard-complete-ring">100%</div><div><div class="eyebrow">Deck complete</div><h2>'+esc(deck.label)+'</h2><p>You remembered every card. This deck has reached 100% <b>'+dp.completionCount+'</b> time'+(dp.completionCount===1?'':'s')+'.</p><div class="flashcard-start-actions"><button type="button" data-fc-start-shuffled>Do another round</button><button type="button" class="secondary" data-fc-reset="'+esc(deck.id)+'">Reset progress</button></div></div></div>';
  }
  const cardId=session.queue[session.index],card=deck.cards.find(function(c){return c.id===cardId});
  if(!card){dp.session=null;saveFlashcardStore(subjectId,store);return renderFlashcardSession(subjectId,deck,store)}
  const phase=session.phase==="first"?"First pass":"Missed-card review • random order";
  const firstDone=session.phase==="first"?session.index:deck.cards.length;
  const pct=deck.cards.length?Math.round(firstDone/deck.cards.length*100):0;
  const remaining=session.phase==="retry"?(session.missed||[]).length:Math.max(0,deck.cards.length-session.index);
  return '<div class="flashcard-session-head"><button type="button" class="secondary" data-fc-back>← All decks</button><div class="flashcard-session-badges"><span>'+esc(phase)+'</span><span class="flashcard-100-badge">'+flashcardProgressBadge(dp)+'</span></div></div>'+
    '<div class="card flashcard-play-card"><div class="flashcard-progress-line"><div><b>'+esc(deck.label)+'</b><span class="small">'+(session.phase==="first"?("Card "+(session.index+1)+" / "+deck.cards.length):(remaining+" still learning"))+'</span></div><div class="flashcard-mini-bar"><i style="width:'+pct+'%"></i></div></div>'+
    '<button type="button" class="flashcard-memory-card '+(session.revealed?'revealed':'')+'" data-fc-flip aria-label="'+(session.revealed?'Hide answer':'Show answer')+'"><span class="flashcard-side-label">'+(session.revealed?'Answer':'Memory card')+'</span><strong>'+esc(session.revealed?card.back:card.front)+'</strong><span class="flashcard-tap-cue">'+(session.revealed?'Press to see the front again':'Press to show answer')+'</span></button>'+
    '<div class="flashcard-play-actions"><button type="button" class="secondary" data-fc-shuffle>Shuffle remaining</button>'+
    (session.revealed?'<button type="button" class="flashcard-missed" data-fc-rate="missed">Haven’t remembered</button><button type="button" class="flashcard-remembered" data-fc-rate="remembered">Remembered</button>':'<button type="button" data-fc-flip>Show answer</button>')+
    '</div><div class="small flashcard-save-note">Saved automatically after every flip, shuffle, and rating.</div></div>';
}
function bindFlashcardControls(root){
  if(!root)return;
  root.querySelectorAll("[data-fc-open]").forEach(function(b){b.onclick=function(){flashcardDeckId=b.dataset.fcOpen;renderFlashcards()}});
  root.querySelectorAll("[data-fc-back]").forEach(function(b){b.onclick=function(){flashcardDeckId=null;renderFlashcards()}});
  root.querySelectorAll("[data-fc-start]").forEach(function(b){b.onclick=function(){startFlashcardCycle(flashcardDeckId,false)}});
  root.querySelectorAll("[data-fc-start-shuffled]").forEach(function(b){b.onclick=function(){startFlashcardCycle(flashcardDeckId,true)}});
  root.querySelectorAll("[data-fc-flip]").forEach(function(b){b.onclick=toggleFlashcardAnswer});
  root.querySelectorAll("[data-fc-shuffle]").forEach(function(b){b.onclick=shuffleFlashcardRemaining});
  root.querySelectorAll('[data-fc-rate="remembered"]').forEach(function(b){b.onclick=function(){rateFlashcard(true)}});
  root.querySelectorAll('[data-fc-rate="missed"]').forEach(function(b){b.onclick=function(){rateFlashcard(false)}});
  root.querySelectorAll("[data-fc-reset]").forEach(function(b){b.onclick=function(){resetFlashcardDeck(b.dataset.fcReset)}});
}
function renderFlashcards(){
  const root=document.getElementById("flashcards");if(!root||!activeUser)return;
  const subjectId=flashcardSubjectId(),name=subjectId==="tu101"?"TU101":"EC214",decks=normalizedFlashcardDecks(subjectId),store=loadFlashcardStore(subjectId);
  if(flashcardDeckId&&!decks.some(function(d){return d.id===flashcardDeckId}))flashcardDeckId=null;
  root.innerHTML='<div class="panel-intro"><div><div class="eyebrow">Active Recall</div><h2>'+name+' Flashcards</h2><p>Part-by-part memory review with cumulative practice and automatic retry of cards you have not remembered yet.</p></div><div class="flashcard-panel-actions"><button type="button" class="secondary" id="resetAllFlashcardsBtn">Reset all flashcard progress</button></div></div>'+
    (flashcardDeckId?renderFlashcardSession(subjectId,flashcardDeck(subjectId,flashcardDeckId),store):renderFlashcardLibrary(subjectId,decks,store));
  const resetAll=root.querySelector("#resetAllFlashcardsBtn");if(resetAll)resetAll.onclick=resetAllFlashcards;
  bindFlashcardControls(root);
}
function ensureFlashcardWorkspace(){
  const nav=document.querySelector("#appShell nav.tabs");
  if(nav&&!nav.querySelector('[data-tab="flashcards"]')){
    const a=document.createElement("a");a.className="tab";a.dataset.tab="flashcards";a.href="/d-study-app/flashcards/";a.textContent="🧠 Flashcards";
    const before=nav.querySelector('[data-tab="history"]');nav.insertBefore(a,before||null);
  }
  const main=document.querySelector("#appShell main.wrap");
  if(main&&!document.getElementById("flashcards")){
    const section=document.createElement("section");section.id="flashcards";section.className="panel";
    const before=document.getElementById("history");main.insertBefore(section,before||null);
  }
}
function flashcardPreviewMarkup(subjectId){
  const name=subjectId==="tu101"?"TU101":"EC214";
  return '<section class="panel active"><div class="panel-intro"><div><div class="eyebrow">Active Recall</div><h2>'+name+' Flashcards</h2><p>The Flashcards workspace is ready, but no study cards have been created yet.</p></div></div>'+flashcardEmptyMarkup(subjectId)+'</section>';
}
